/**
 * Rigor overlay (REQ-VR-005): the strictness ladder tiny-spec → spec-first → spec-anchored →
 * spec-as-code (legacy name spec-as-source) composed on top of the variant playbook. Spec-anchored adds the
 * steps of `base/spec-anchored` (design validation, Gherkin, waves, validation, audit bundle, archive);
 * spec-as-code adds those of `base/spec-as-code` too (discovery, contracts, audit). Steps the variant
 * cannot feed (a delta-based brownfield flow has no requirements for Gherkin) are skipped with the reason.
 */
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { checkPlaybook, findPlaybook } from './playbook.js';
const OVERLAYS = { 'tiny-spec': [], 'spec-first': [], 'spec-anchored': ['base/spec-anchored'], 'spec-as-code': ['base/spec-anchored', 'base/spec-as-code'] };
export const applyRigor = async (cwd, feature, base, rigor, values) => {
    if (!OVERLAYS[rigor].length)
        return { playbook: base, added: [], skipped: [], file: null };
    const phases = [];
    const baseChecked = await checkPlaybook(cwd, (await findPlaybook(cwd, base)).playbook, values);
    // A step the variant already has (in any phase) is not added twice.
    const have = new Set(baseChecked.steps.map((x) => x.id));
    for (const o of OVERLAYS[rigor]) {
        const found = await findPlaybook(cwd, o);
        for (const ph of found?.playbook.phases ?? []) {
            const t = phases.find((p) => p.id === ph.id);
            if (t)
                t.steps.push(...ph.steps);
            else
                phases.push({ id: ph.id, steps: [...ph.steps] });
        }
    }
    for (const ph of phases)
        ph.steps = ph.steps.filter((st) => !have.has(st.id ?? st.use.split('/').pop() ?? st.use));
    const name = `${feature}-${rigor}`;
    let pb = { name, extends: base, description: `${base} at rigor ${rigor} (generated by open-sdd start)`, phases };
    const skipped = [];
    for (let round = 0; round < 10; round += 1) {
        const r = await checkPlaybook(cwd, pb, values);
        const starved = r.issues.filter((i) => i.code === 'STARVED_STEP');
        if (!starved.length) {
            const added = r.steps.filter((s) => s.decision === 'EXECUTE' && !baseChecked.steps.some((b) => b.id === s.id)).map((s) => s.id);
            const file = path.join(cwd, '.sdd', 'playbooks', `${name}.playbook.json`);
            await mkdir(path.dirname(file), { recursive: true });
            await writeFile(file, `${JSON.stringify(pb, null, 2)}\n`, 'utf8');
            return { playbook: name, added, skipped, file };
        }
        for (const i of starved) {
            const id = i.message.match(/^step «([^»]+)»/)?.[1];
            if (id && !skipped.some((s) => s.id === id))
                skipped.push({ id, reason: `not applicable to ${base}: ${i.message}` });
        }
        pb = { ...pb, customize: [{ skip: skipped.map((s) => s.id) }] };
    }
    return { playbook: base, added: [], skipped, file: null };
};
